import sqlite3
import json
import uuid
import struct
from typing import List

from fastapi import FastAPI, File, Form, UploadFile, HTTPException, Depends, Header, status
from fastapi.responses import Response

app = FastAPI()
DATABASE = "db.sqlite3"

def get_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_connection()
    try:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS recipes (
                recipe_id TEXT PRIMARY KEY,
                owner_id TEXT NOT NULL,
                location_name TEXT NOT NULL,
                photo BLOB NOT NULL,
                authorized_viewers TEXT NOT NULL
            )
        """)
        conn.commit()
    finally:
        conn.close()

@app.on_event("startup")
def startup():
    init_db()

async def get_api_key(api_key: str = Header(..., alias="X-API-Key")) -> str:
    return api_key

# --- Image sanitization helpers (standard library only) ---

def strip_png_metadata(data: bytes) -> bytes:
    """Keep only critical PNG chunks (IHDR, PLTE, IDAT, IEND) to remove all metadata."""
    if data[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError("Not a valid PNG file")
    out = bytearray(data[:8])
    pos = 8
    critical = {b'IHDR', b'PLTE', b'IDAT', b'IEND'}
    while pos < len(data):
        if pos + 8 > len(data):
            break
        length = struct.unpack('>I', data[pos:pos+4])[0]
        chunk_type = data[pos+4:pos+8]
        chunk_total = 4 + 4 + length + 4
        if pos + chunk_total > len(data):
            break
        if chunk_type in critical:
            out.extend(data[pos:pos+chunk_total])
        pos += chunk_total
    return bytes(out)

def strip_jpeg_metadata(data: bytes) -> bytes:
    """Remove APP1, APP13 and COM markers (EXIF/XMP/IPTC/comments) from a JPEG file."""
    if data[:2] != b'\xff\xd8':
        raise ValueError("Not a valid JPEG file")
    out = bytearray(b'\xff\xd8')
    pos = 2
    # Markers to completely remove (APP1, APP13, COM)
    REMOVE_MARKERS = {0xe1, 0xed, 0xfe}

    while pos < len(data) - 1:
        if data[pos] != 0xff:
            # fallback: copy remaining bytes (should not happen in a valid JPEG)
            out.extend(data[pos:])
            break
        marker = data[pos+1]

        if marker == 0xd8:          # SOI (should not appear after the first)
            out.append(0xff)
            out.append(marker)
            pos += 2
            continue
        if marker == 0xd9:          # EOI
            out.extend(data[pos:pos+2])
            pos += 2
            break
        if 0xd0 <= marker <= 0xd7:  # RST markers (no payload)
            out.extend(data[pos:pos+2])
            pos += 2
            continue

        if marker == 0xda:          # SOS – start of scan
            if pos + 4 > len(data):
                break
            length = (data[pos+2] << 8) | data[pos+3]
            out.extend(data[pos:pos+2+length])
            pos += 2 + length
            # copy raw scan data until EOI, respecting 0xFF 0x00 stuff bytes
            while pos < len(data) - 1:
                if data[pos] == 0xff:
                    if data[pos+1] == 0x00:
                        out.append(0xff)
                        out.append(0x00)
                        pos += 2
                    elif data[pos+1] == 0xd9:
                        out.append(0xff)
                        out.append(0xd9)
                        pos += 2
                        break
                    elif 0xd0 <= data[pos+1] <= 0xd7:
                        out.append(0xff)
                        out.append(data[pos+1])
                        pos += 2
                    else:
                        # unexpected – copy byte as-is
                        out.append(data[pos])
                        pos += 1
                else:
                    out.append(data[pos])
                    pos += 1
            break

        # markers with a length field
        if pos + 3 >= len(data):
            break
        length = (data[pos+2] << 8) | data[pos+3]
        if length < 2:
            break
        segment_len = length + 2
        if pos + segment_len > len(data):
            break

        if marker in REMOVE_MARKERS:
            pos += segment_len
            continue

        out.extend(data[pos:pos+segment_len])
        pos += segment_len

    if out[-2:] != b'\xff\xd9':
        out.extend(b'\xff\xd9')
    return bytes(out)

def sanitize_photo(data: bytes) -> bytes:
    """Detect image type and strip invisible metadata."""
    if data.startswith(b'\x89PNG\r\n\x1a\n'):
        return strip_png_metadata(data)
    if data.startswith(b'\xff\xd8'):
        return strip_jpeg_metadata(data)
    raise ValueError("Unsupported image format")

def get_media_type(data: bytes) -> str:
    if data.startswith(b'\xff\xd8'):
        return "image/jpeg"
    if data.startswith(b'\x89PNG\r\n\x1a\n'):
        return "image/png"
    return "application/octet-stream"

# --- API endpoints ---

@app.post("/recipes", status_code=201)
async def create_recipe(
    photo: UploadFile = File(...),
    locationName: str = Form(...),
    authorizedViewers: List[str] = Form(...),
    api_key: str = Depends(get_api_key)
):
    recipe_id = str(uuid.uuid4())
    photo_bytes = await photo.read()

    # Strip invisible metadata before storage
    try:
        photo_bytes = sanitize_photo(photo_bytes)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid or unsupported image file")

    auth_json = json.dumps(authorizedViewers)
    conn = get_connection()
    try:
        conn.execute(
            "INSERT INTO recipes (recipe_id, owner_id, location_name, photo, authorized_viewers) VALUES (?, ?, ?, ?, ?)",
            (recipe_id, api_key, locationName, photo_bytes, auth_json)
        )
        conn.commit()
    finally:
        conn.close()
    return {"recipeId": recipe_id}

@app.get("/recipes/{recipeId}")
def get_recipe(recipeId: str, api_key: str = Depends(get_api_key)):
    conn = get_connection()
    try:
        row = conn.execute("SELECT * FROM recipes WHERE recipe_id=?", (recipeId,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Recipe not found")
        owner_id = row["owner_id"]
        auth_list = json.loads(row["authorized_viewers"])
        if api_key != owner_id and api_key not in auth_list:
            raise HTTPException(status_code=404, detail="Recipe not found")
        photo_url = f"/recipes/{recipeId}/photo"
        recipe = {
            "recipeId": row["recipe_id"],
            "locationName": row["location_name"],
            "photoUrl": photo_url,
            "authorizedViewers": auth_list,
            "ownerId": owner_id
        }
        return recipe
    finally:
        conn.close()

@app.get("/recipes/{recipeId}/photo")
def get_photo(recipeId: str, api_key: str = Depends(get_api_key)):
    conn = get_connection()
    try:
        row = conn.execute("SELECT photo, owner_id, authorized_viewers FROM recipes WHERE recipe_id=?", (recipeId,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Recipe not found")
        owner_id = row["owner_id"]
        auth_list = json.loads(row["authorized_viewers"])
        if api_key != owner_id and api_key not in auth_list:
            raise HTTPException(status_code=404, detail="Recipe not found")
        photo_bytes = row["photo"]
        media_type = get_media_type(photo_bytes)
    finally:
        conn.close()
    return Response(content=photo_bytes, media_type=media_type)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
